use super::*;

fn fixture()->Value{json!({"events":[{"id":"canon-event","title":"حدث 中文"}],"boards":[{"id":"board","name":"Board","groups":[{"id":"group","name":"نور مِ 明 e\u{301} 👩🏽‍🚀"}],"cards":[{"id":"card","title":"𠀀 字","body":"exact \u{e000}","kind":"scene","reference":{"kind":"scene","id":"scene"},"x":800,"y":500,"groupId":"group","labels":["يَكشف","e\u{301}","👩🏽‍🚀","\u{e000}"]},{"id":"other","title":"Elsewhere","x":1200,"y":700,"kind":"note","groupId":null,"labels":[]}],"edges":[{"id":"edge","fromId":"card","toId":"other","kind":"reference","confirmed":false}]}]})}

#[test]
fn scale_and_pan_coordinates_are_inverted_once(){
    for zoom in [0.4,0.5,1.,1.5]{let x=840.*zoom;let y=520.*zoom;assert_eq!(to_world(x,y,zoom),Some((840.,520.)));let drag=Drag{board:"board".into(),card:"card".into(),offset:(40.,20.),zoom,view_generation:0,data_epoch:1};assert_eq!(drag.position(940.*zoom,620.*zoom,(2800.,1800.)),Some((900.,600.)));}
    // Event positions belong to the entire scrolled drawing area. A nonzero
    // scroll offset changes visibility, not the inverse transform.
    assert_eq!(to_world(470.,310.,0.5),Some((940.,620.)));
    assert_eq!(to_world(f64::NAN,10.,1.),None);assert_eq!(to_world(0.,0.,0.),None);
    let drag=Drag{board:"board".into(),card:"card".into(),offset:(40.,20.),zoom:0.5,view_generation:0,data_epoch:1};assert_eq!(drag.position(-20.,-20.,(2800.,1800.)),Some((0.,0.)));assert_eq!(drag.position(1e9,1e9,(2800.,1800.)),Some((2580.,1690.)));
}
#[test]
fn local_view_changes_refuse_stale_drag_and_never_rewrite_coordinates(){
    let data=fixture();let original=data.clone();let mut view=ViewState::default();let drag=Drag{board:"board".into(),card:"card".into(),offset:(0.,0.),zoom:1.,view_generation:0,data_epoch:7};assert!(drag.valid(&view,7,"board"));assert!(!drag.valid(&view,8,"board"));assert!(!drag.valid(&view,7,"another"));view.set_query("مِ");assert!(!drag.valid(&view,7,"board"));view.set_zoom(2.);assert_eq!(view.zoom,1.5);view.set_group("group");assert_eq!(data,original);
    assert_eq!(bounds(&[json!({"x":1e10,"y":1e10})]),(MAX_EXTENT,MAX_EXTENT));
}
#[test]
fn authored_unicode_group_and_label_filters_are_exact_and_read_only(){
    let data=fixture();let board=&data["boards"][0];let groups=group_names(board);let card=&board["cards"][0];let mut view=ViewState::default();for query in ["مِ","明","𠀀","e\u{301}","👩🏽‍🚀","\u{e000}"]{view.set_query(query);assert!(matches(card,&view,&groups),"{query}");}view.set_group("group");view.set_query("");assert!(!matches(&board["cards"][1],&view,&groups));let regions=group_rectangles(&[card],&groups);assert_eq!(regions[0].0,groups["group"]);assert_eq!(regions[0].1,Rect{x:792.,y:476.,width:236.,height:142.});let mut historical=card.clone();historical["groupId"]=json!("missing");assert!(card_metadata(&historical,&groups).0.contains("Missing group"));assert!(group_rectangles(&[&historical],&groups).is_empty());assert_eq!(data,fixture());
}
#[test]
fn group_and_labels_change_only_the_selected_board_representation(){
    let mut data=fixture();let original=data.clone();let board=data["boards"][0].clone();change_group(&mut data,"board",&board,"new",Some("مجموعة 中文 e\u{301}")).unwrap();let expected=data["boards"][0]["cards"][0].clone();let labels=vec!["مِ 👩🏽‍🚀 \u{e000}".into(),"e\u{301}".into()];edit_card(&mut data,"board",&expected,Some("new"),labels.clone()).unwrap();assert_eq!(data["boards"][0]["cards"][0]["labels"],json!(labels));let board=data["boards"][0].clone();change_group(&mut data,"board",&board,"new",Some("改名 مِ")).unwrap();let board=data["boards"][0].clone();change_group(&mut data,"board",&board,"new",None).unwrap();assert!(data["boards"][0]["cards"][0]["groupId"].is_null());for key in ["id","kind","reference","title","body","x","y"]{assert_eq!(data["boards"][0]["cards"][0][key],original["boards"][0]["cards"][0][key]);}assert_eq!(data["events"],original["events"]);assert_eq!(data["boards"][0]["cards"][1],original["boards"][0]["cards"][1]);assert_eq!(data["boards"][0]["edges"],original["boards"][0]["edges"]);
}
#[test]
fn stale_or_ambiguous_author_choices_fail_without_partial_changes(){
    let mut data=fixture();let old=data["boards"][0].clone();let card=old["cards"][0].clone();data["boards"][0]["cards"][0]["body"]=json!("new body");let current=data.clone();assert!(edit_card(&mut data,"board",&card,None,vec![]).unwrap_err().contains("changed"));assert!(change_group(&mut data,"board",&old,"group",None).unwrap_err().contains("changed"));assert_eq!(data,current);let current_card=data["boards"][0]["cards"][0].clone();assert!(edit_card(&mut data,"board",&current_card,Some("unknown"),vec![]).is_err());assert_eq!(data,current);
    data["boards"][0]["cards"].as_array_mut().unwrap().push(current_card.clone());let current=data.clone();assert!(edit_card(&mut data,"board",&current_card,None,vec![]).unwrap_err().contains("ambiguous"));assert_eq!(data,current);
}
#[test]
fn unchanged_historical_missing_group_is_preserved_when_labels_change(){
    let mut data=fixture();data["boards"][0]["cards"][0]["groupId"]=json!("missing");let card=data["boards"][0]["cards"][0].clone();edit_card(&mut data,"board",&card,Some("missing"),vec!["新 مِ".into()]).unwrap();assert_eq!(data["boards"][0]["cards"][0]["groupId"],"missing");assert_eq!(labels_from_text("مِ\ne\u{301}\n"),vec!["مِ","e\u{301}",""]);
}

fn wait(condition:impl Fn()->bool){use std::time::{Duration,Instant};let start=Instant::now();let context=glib::MainContext::default();while !condition(){while context.pending(){context.iteration(false);}assert!(start.elapsed()<Duration::from_secs(20),"board GTK callback timed out");std::thread::sleep(Duration::from_millis(5));}while context.pending(){context.iteration(false);}}
fn pump(){let start=std::time::Instant::now();wait(||start.elapsed()>=std::time::Duration::from_millis(90));}
fn rpc(client:&crate::process::Process,op:&str,args:Value)->Value{let result=Rc::new(RefCell::new(None));let out=result.clone();client.rpc(op,args,move|r|*out.borrow_mut()=Some(r));wait(||result.borrow().is_some());let reply=result.borrow_mut().take().unwrap().unwrap();reply}
fn find<T:glib::object::IsA<gtk::Widget>+glib::object::ObjectType>(widget:&gtk::Widget,predicate:&impl Fn(&T)->bool)->Option<T>{if let Ok(value)=widget.clone().downcast::<T>(){if predicate(&value){return Some(value);}}if let Ok(container)=widget.clone().downcast::<gtk::Container>(){for child in container.children(){if let Some(value)=find(&child,predicate){return Some(value);}}}None}
fn combo(widget:&gtk::Widget,name:&str)->gtk::ComboBoxText{find(widget,&|c:&gtk::ComboBoxText|c.tooltip_text().as_deref()==Some(name)).unwrap()}
fn button(widget:&gtk::Widget,name:&str)->gtk::Button{find(widget,&|b:&gtk::Button|b.label().as_deref()==Some(name)||b.tooltip_text().as_deref()==Some(name)).unwrap_or_else(||panic!("Missing board control: {name}"))}
fn saved(page:&Rc<DataPage>)->Result<(),String>{let result=Rc::new(RefCell::new(None));let out=result.clone();page.save(move|r|*out.borrow_mut()=Some(r));wait(||result.borrow().is_some());let reply=result.borrow_mut().take().unwrap();reply}
fn pointer(area:&gtk::DrawingArea,x:f64,y:f64,down:bool){use glib::translate::ToGlibPtr;let mut event=gdk::Event::new(if down{gdk::EventType::ButtonPress}else{gdk::EventType::ButtonRelease});let raw=event.downcast_mut::<gdk::EventButton>().unwrap().as_mut();raw.window=area.window().unwrap().to_glib_full();raw.button=1;raw.x=x;raw.y=y;area.emit_by_name::<bool>(if down{"button-press-event"}else{"button-release-event"},&[&event]);}
fn motion(area:&gtk::DrawingArea,x:f64,y:f64){use glib::translate::ToGlibPtr;let mut event=gdk::Event::new(gdk::EventType::MotionNotify);let raw=event.downcast_mut::<gdk::EventMotion>().unwrap().as_mut();raw.window=area.window().unwrap().to_glib_full();raw.state=gdk::ModifierType::BUTTON1_MASK.bits();raw.x=x;raw.y=y;area.emit_by_name::<bool>("motion-notify-event",&[&event]);}

/// Callable only from the root's serialized, opt-in GTK harness. Uses synthetic
/// signal events and authored data, with the actual companion and draw widget.
pub(crate) fn run(binaries:&std::path::Path){
    let fixture_dir=tempfile::tempdir().unwrap();let data_dir=fixture_dir.path().join("board-viewport");std::fs::create_dir_all(&data_dir).unwrap();let binary=if binaries.join("novel-companion-rust").is_file(){"novel-companion-rust"}else{"novel-companion"};let client=crate::process::Process::start(&binaries.join(binary),&data_dir,true).unwrap();let novel=rpc(&client,"create_novel",json!({"title":"Board viewport fixture"}));let pid=novel["project"]["id"].as_str().unwrap();let sid=novel["scene"]["id"].as_str().unwrap();let scene=rpc(&client,"load_scene",json!({"sceneId":sid}));
    let mut initial=crate::tools::initial("planning");initial["boards"]=fixture()["boards"].clone();initial["boards"][0]["cards"][0]["reference"]["id"]=json!(sid);let stored=rpc(&client,"save_project_data",json!({"projectId":pid,"kind":"planning","payload":initial,"parent":null}));let page=DataPage::new(client.clone(),"planning");page.load(pid,vec![(sid.into(),"Scene".into())]);wait(||page.loaded.get());
    let window=gtk::Window::new(gtk::WindowType::Toplevel);window.set_accept_focus(false);window.set_focus_on_map(false);window.set_keep_below(true);window.set_default_size(1150,800);let board=build(page.clone(),window.clone());let controls=board.children()[0].clone();board.remove(&controls);let sidebar=gtk::ScrolledWindow::new(None::<&gtk::Adjustment>,None::<&gtk::Adjustment>);sidebar.set_size_request(300,-1);sidebar.add(&controls);let layout=gtk::Box::new(gtk::Orientation::Horizontal,6);layout.pack_start(&sidebar,false,false,0);layout.pack_start(&board,true,true,0);window.add(&layout);window.show_all();pump();window.check_resize();let root:gtk::Widget=layout.upcast();let area=find(&root,&|_:&gtk::DrawingArea|true).unwrap();let scroll=find(&board.clone().upcast(),&|_:&gtk::ScrolledWindow|true).unwrap();let zoom=find(&root,&|s:&gtk::SpinButton|s.tooltip_text().as_deref()==Some("Board zoom percent")).unwrap();let filter=find(&root,&|e:&gtk::Entry|e.tooltip_text().as_deref()==Some("Filter board cards")).unwrap();let group=combo(&root,"Filter board group");let epoch=page.epoch.get();
    filter.set_text("يَكشف");group.set_active_id(Some("group"));zoom.set_value(150.);pump();assert_eq!(area.width_request(),4200);assert_eq!(area.height_request(),2700);button(&root,"Pan right").clicked();button(&root,"Pan down").clicked();assert!(scroll.hadjustment().value()>0.);assert_eq!(*page.value.borrow(),initial);assert_eq!(page.epoch.get(),epoch);assert!(!page.dirty.get());assert_eq!(rpc(&client,"load_project_data",json!({"projectId":pid,"kind":"planning"})),stored);
    button(&root,"Reset view").clicked();zoom.set_value(50.);pump();scroll.hadjustment().set_value(100.);scroll.vadjustment().set_value(60.);assert_eq!(area.width_request(),1400);pointer(&area,420.,260.,true);motion(&area,470.,310.);pointer(&area,470.,310.,false);assert_eq!(page.value.borrow()["boards"][0]["cards"][0]["x"],900.);assert_eq!(page.value.borrow()["boards"][0]["cards"][0]["y"],600.);assert!(page.dirty.get());assert_eq!(rpc(&client,"load_project_data",json!({"projectId":pid,"kind":"planning"})),stored);saved(&page).unwrap();let moved=page.value.borrow().clone();assert_eq!(moved["boards"][0]["cards"][0]["reference"],initial["boards"][0]["cards"][0]["reference"]);
    pointer(&area,470.,310.,true);filter.set_text("Elsewhere");motion(&area,500.,350.);pointer(&area,500.,350.,false);assert_eq!(*page.value.borrow(),moved);filter.set_text("");pointer(&area,470.,310.,true);let mut unrelated=moved.clone();unrelated["boards"][0]["cards"][1]["body"]=json!("unrelated draft change");page.update(unrelated.clone());motion(&area,500.,350.);pointer(&area,500.,350.,false);assert_eq!(*page.value.borrow(),unrelated);page.discard();assert_eq!(*page.value.borrow(),moved);
    button(&root,"Refresh card choices").clicked();let author=find(&root,&|e:&gtk::Expander|e.label().as_deref()==Some("Labels and groups")).unwrap();author.set_expanded(true);combo(&root,"Card labels and group").set_active_id(Some("card"));let names=find(&root,&|e:&gtk::Entry|e.placeholder_text().as_deref()==Some("Group name")).unwrap();names.set_text("مجموعة 中文 e\u{301}");button(&root,"Add group to draft").clicked();let created=page.value.borrow()["boards"][0]["groups"].as_array().unwrap().last().unwrap()["id"].as_str().unwrap().to_owned();combo(&root,"Selected card group").set_active_id(Some(&created));let labels=find(&root,&|t:&gtk::TextView|t.tooltip_text().as_deref()==Some("Selected card labels, one per line")).unwrap();let exact="مِ 👩🏽‍🚀 \u{e000}\ne\u{301} 𠀀";labels.buffer().unwrap().set_text(exact);assert_eq!(page.value.borrow()["boards"][0]["cards"][0]["labels"],json!(labels_from_text(exact)));assert_eq!(page.value.borrow()["boards"][0]["cards"][0]["groupId"],created);assert!(page.dirty.get());let before_author_save=rpc(&client,"load_project_data",json!({"projectId":pid,"kind":"planning"}));assert_eq!(before_author_save["payload"],moved);saved(&page).unwrap();
    combo(&root,"Group to rename or ungroup").set_active_id(Some(&created));names.set_text("改名 مِ");button(&root,"Rename group in draft").clicked();button(&root,"Ungroup cards and remove group").clicked();assert!(page.value.borrow()["boards"][0]["cards"][0]["groupId"].is_null());assert_eq!(page.value.borrow()["boards"][0]["cards"][0]["labels"],json!(labels_from_text(exact)));page.discard();button(&root,"Refresh card choices").clicked();assert_eq!(page.value.borrow()["boards"][0]["cards"][0]["groupId"],created);
    // An external competing save is refused without losing the local author
    // draft. Neither view actions nor group edits touch the manuscript head.
    let prior=rpc(&client,"load_project_data",json!({"projectId":pid,"kind":"planning"}));let mut external=prior["payload"].clone();external["boards"][0]["name"]=json!("External board name");let external=rpc(&client,"save_project_data",json!({"projectId":pid,"kind":"planning","payload":external,"parent":prior["revisionId"]}));combo(&root,"Card labels and group").set_active_id(Some("card"));labels.buffer().unwrap().set_text("local competing label مِ");let draft=page.value.borrow().clone();assert!(saved(&page).is_err());assert!(page.dirty.get());assert_eq!(*page.value.borrow(),draft);assert_eq!(rpc(&client,"load_project_data",json!({"projectId":pid,"kind":"planning"})),external);assert_eq!(rpc(&client,"load_scene",json!({"sceneId":sid})),scene);window.close();pump();client.stop();
}
